const express = require("express");
const db = require("../db");

const router = express.Router();

// :id must be the caller's own account; scoping by req.user.accountId (not
// the URL param) keeps a session from ever touching another account's row.
router.patch("/:id", async (req, res) => {
  if (req.params.id !== req.user.accountId) return res.status(404).end();
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 RETURNING *",
    [req.body.display_name, req.body.billing_email, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  if (req.params.id !== req.user.accountId) return res.status(404).end();
  const row = await db.write("UPDATE accounts SET deleted_at = now() WHERE id = $1 RETURNING id",
    [req.user.accountId]);
  if (!row) return res.status(404).end();
  res.status(204).end();
});

module.exports = router;

routes/orders.js.text:
const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key");
  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header is required" });
  }

  // ON CONFLICT ... DO UPDATE (a no-op update) is the standard trick to make
  // a retried insert RETURNING the original row instead of nothing, in one
  // round trip; xmax = 0 tells us whether this call did the inserting.
  const row = await db.write(
    `INSERT INTO orders (account_id, sku, quantity, idempotency_key)
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (account_id, idempotency_key)
     DO UPDATE SET account_id = orders.account_id
     RETURNING *, (xmax = 0) AS inserted`,
    [req.user.accountId, req.body.sku, req.body.quantity, idempotencyKey]
  );
  const { inserted, ...order } = row;

  if (!inserted && (order.sku !== req.body.sku || order.quantity !== req.body.quantity)) {
    return res.status(409).json({ error: "Idempotency-Key already used with different request parameters" });
  }

  res.status(inserted ? 201 : 200).json(order);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

