const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key");
  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header is required" });
  }

  // Replays of a key we've already seen skip the write entirely.
  const existing = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, idempotencyKey]
  );
  if (existing.length) return res.status(201).json(existing[0]);

  // ON CONFLICT DO NOTHING makes the insert itself race-safe: if two requests
  // with the same key land concurrently, only one row is created.
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) " +
      "ON CONFLICT (account_id, idempotency_key) DO NOTHING RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, idempotencyKey]
  );
  if (row) return res.status(201).json(row);

  // Lost the race — the other request's row is the result to return.
  const [winner] = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, idempotencyKey]
  );
  res.status(201).json(winner);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

turns.text:
Walking through `db.write()` stage by stage — there are several distinct drop points, and they don't all behave the same way.

```js
async function write(text, params) {
  const client = await pool.connect();       // (1)
  try {
    await client.query("BEGIN");              // (2)
    const res = await client.query(text, params); // (3)
    await client.query("COMMIT");              // (4)
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");            // (5)
    throw err;
  } finally {
    client.release();                          // (6)
  }
}
```

**(1) Drop during `pool.connect()`** — this call is *outside* the try block. If it rejects, `write()` throws immediately, nothing was ever acquired, so there's nothing to roll back or release. Clean failure, but see below for what happens to that rejection.

**(2)/(3) Drop during `BEGIN` or the write query itself** — `client.query` throws, control goes to `catch`. The `catch` block unconditionally calls `client.query("ROLLBACK")` on a connection that's already dead. That call itself throws, and *that* new error is what actually propagates — the original error is swallowed and replaced. `finally` still runs `client.release()`. On the DB side this part is actually safe: since `COMMIT` never ran, Postgres tears down the backend session and the transaction is discarded server-side. No partial write lands.

**(4) Drop during `COMMIT` — the dangerous one.** This is the classic in-doubt-transaction problem:
- If the connection dies before the server ever processes the COMMIT, nothing is persisted — consistent with the client seeing an error.
- If the connection dies *after* the server commits but *before* the acknowledgment reaches the client, the write **did** land in the database, but the code still takes the `catch` path (attempts a ROLLBACK that fails, same as above) and reports failure. The caller of the route has no way to distinguish "definitely failed" from "succeeded, ack lost." If anything upstream retries on error (a client retry, a queue redelivery), a non-idempotent write like `POST /orders` could get created twice.

**(5)/(6)** As noted, the ROLLBACK-on-a-dead-connection failure means the real error is usually masked — you'd see something like a connection-closed error rather than the original cause.

**Then it gets worse one level up.** None of the route handlers wrap `db.write()` in try/catch, there's no Express error-handling middleware in `app.js`, and there's no `pool.on('error', ...)` listener on the pg Pool. So whatever error finally escapes `write()`:
- Never gets turned into an HTTP response — the original caller's request just hangs until *their* client-side timeout.
- Becomes an unhandled promise rejection in Node, which (default behavior since Node 15) **crashes the whole process** — taking down every other in-flight request on that server, not just this one.

So the practical failure mode isn't usually a silent partial write (Postgres protects you there except at the COMMIT-ack edge case) — it's a hung request plus a real chance of taking the entire process down.

Want me to harden this — add a global error handler / `pool.on('error')` listener and try/catch around the route handlers so a dropped connection returns a 5xx instead of crashing the server?

